namespace ghidra.app.util.viewer.field;

using docking.widgets.fieldpanel;
using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra.program.model.address;
using ghidra.program.util;

public class ListingFieldDescriptionProvider : FieldDescriptionProvider {
	private bool verbose = false;
	/* @Override */
	public string getDescription(FieldLocation loc, Field field) {
		if (!(field is ListingField listingField)) {
			return "No program open";
		}
		FieldFactory fieldFactory = listingField.getFieldFactory();
		StringBuilder buf = new StringBuilder(fieldFactory.getFieldName());
		if (verbose) {
			ProgramLocation location = fieldFactory.getProgramLocation(0, 0, listingField);
			if (location != null) {
				Address address = location.getAddress();
				buf.append(" Field at Address ");
				buf.append(address.toString(address.getAddressSpace().showSpaceName(), 1));
			}
		}
		buf.append(": ");
		buf.append(field.getText());
		return buf.toString();
	}

	public void setVerbose(bool b) {
		this.verbose = b;
	}
}
